CsrHopLayer::SendRoutingControl (
  CsrNodeId dst,
  Ptr<Packet> payload)
{
  SendRoutingControl (
    std::vector<CsrNodeId> {dst},
    payload);
}

void
CsrHopLayer::SendRoutingControl (
  const std::vector<CsrNodeId> &destinations,
  Ptr<Packet> payload)
{
  NS_ASSERT (m_mac != nullptr);
  NS_ABORT_MSG_IF (
    destinations.empty () ||
      destinations.size () > CsrHeader::MAX_DESTINATIONS,
    "reliable routing control requires 1 to 10 destinations");

  std::vector<CsrHeader::DestinationSequence> targets;
  targets.reserve (destinations.size ());

  for (CsrNodeId destination : destinations)
    {
      uint16_t &lastSeq =
        m_lastSentSeqByDest[destination];
      uint16_t sequence =
        static_cast<uint16_t> (
          (lastSeq + 1) & 0xFFFF);
      lastSeq = sequence;
      targets.emplace_back (
        destination,
        sequence);
    }

  CsrNodeId primaryDestination =
    targets.front ().first;
  uint16_t primarySequence =
    targets.front ().second;

  CsrHeader hdr (
    m_nodeId,
    primaryDestination,
    primarySequence,
    7,
    true,
    false);

  hdr.SetType (CSR_PKT_ROUTING_CONTROL);
  hdr.SetDestType (CSR_DEST_MULTICAST);
  hdr.SetDestinationSequences (targets);
  hdr.SetSecurityCount (m_hopSecurity.GetOwnSecurityCount ());
  hdr.SetHasGroupSecurity (true);
  ApplyLinkControl (hdr, destinations);

CsrMacCore::CancelAcknowledgedFrames (CsrNodeId neighbor,
                                      uint16_t baseSeq,
                                      uint64_t ackBitmap,
                                      uint64_t dackBitmap)
{
  // DACK is also terminal at MAC: HOP moves that packet to its delayed DACK
  // list, so another queued over-the-air copy must not be transmitted.
  uint64_t completedBitmap = ackBitmap | dackBitmap;
  uint32_t removed = 0;

  for (auto it = m_queue.begin (); it != m_queue.end (); )
    {
      if (!it->ackable || it->dest != neighbor || it->frame == nullptr)
        {
          ++it;
          continue;
        }

      CsrHeader queuedHeader;
      if (!it->frame->PeekHeader (queuedHeader))
        {
          ++it;
          continue;
        }

      // OPNET's exact-ACK MAC cleanup compares the outer integer
      // destination.  A routing-control packet with a destination structure
      // is therefore left intact, even after one member of the group ACKs.
      if (queuedHeader.HasDestinationSequences ())
        {
          ++it;
          continue;
        }

      // Unsigned subtraction gives the sequence's age modulo 2^16, matching
      // the 16-bit legacy sequence space even across wraparound.
      uint16_t age = static_cast<uint16_t> (
        baseSeq - queuedHeader.GetSeq ());

      if (age < 64 && (completedBitmap & (1ULL << age)) != 0)
        {
          std::cout << "[MAC " << m_nodeId
                    << "] Cancel queued acknowledged frame"
                    << " neighbor=" << neighbor
                    << " seq=" << queuedHeader.GetSeq ()
                    << " baseSeq=" << baseSeq
                    << " windowIndex=" << age
                    << std::endl;

          it = m_queue.erase (it);
          removed++;
          continue;
        }

      ++it;
    }
